//! Automatic product execution plans, not user quotas. The storage owner supplies
//! observed durable outcomes and immutable index batches. No provider I/O or truth certification.
use crate::common::{a,canonical_hash as hash,error,s,Result};
use serde_json::{json,Value};
use std::collections::BTreeSet;
pub const VERSION:&str="lightog-source-execution/0.1";
fn need(ok:bool,c:&str)->Result<()>{if ok{Ok(())}else{Err(error(c,c))}}
fn sealed(v:&Value)->String{let mut x=v.clone();x.as_object_mut().unwrap().remove("record_sha256");hash(&x)}
fn seal(v:&mut Value){v["record_sha256"]=json!(sealed(v));}
fn binding(scope:&Value)->Result<String>{need(scope["version"]=="lightog-source-product-budget/1"&&["ASK","SOURCE_LEARNING"].contains(&s(&scope["context"]["operation"]))&&scope["source_stamp"].is_object()&&scope["snapshot"].is_object()&&scope["models"].is_object()&&scope["context"]["question"].as_str().is_some_and(|x|!x.trim().is_empty()),"SOURCE_EXECUTION_SCOPE_INVALID")?;Ok(hash(scope))}
fn check(c:&Value,scope:&Value)->Result<()>{need(c["contract_version"]==VERSION&&c["mode"]=="AUTOMATIC_TASK_PLAN"&&c["status"]=="AUTHORIZED"&&c["record_sha256"]==sealed(c)&&c["scope_sha256"]==binding(scope)?&&c.get("limits").is_none(),"SOURCE_EXECUTION_CONTEXT_CHANGED")}
fn phase(cap:&str,n:u64,tokens:u64)->Value{json!({"capability":cap,"planned_calls":n,"max_output_tokens":if cap=="generation"{Value::Null}else{json!(tokens)}})}
fn reviewed_policy(policy:&str)->bool{["source-learning-product-candidate-reviewed-batched-local-v1","source-learning-product-rebuild-candidate-reviewed-batched-local-v1"].contains(&policy)}
fn batched_policy(policy:&str)->bool{policy.contains("candidate-mvp-batched")||reviewed_policy(policy)}
fn create(p:&Value)->Result<Value>{let scope=&p["scope"];let h=binding(scope)?;let k=s(&p["execution_key"]);need(!k.is_empty()&&k.len()<=256,"SOURCE_EXECUTION_KEY_INVALID")?;let mut phases=json!({});let op=s(&scope["context"]["operation"]);
 if op=="ASK"{let e=&p["embedding_plan"];need(e["scope_sha256"]==h&&e["status"]=="READY"&&e["point_in_time_only"]==true,"SOURCE_EXECUTION_EMBEDDING_PLAN_INVALID")?;for name in ["document_batches","query_batches"]{need(e[name].as_u64().is_some(),"SOURCE_EXECUTION_EMBEDDING_PLAN_INVALID")?;}phases["ANSWER_GENERATION"]=phase("generation",1,5000);phases["ANSWER_REVIEW"]=phase("generation",1,8000);phases["SOURCE_DOCUMENT_EMBEDDING"]=phase("embedding",e["document_batches"].as_u64().unwrap(),0);phases["SOURCE_QUERY_EMBEDDING"]=phase("embedding",e["query_batches"].as_u64().unwrap(),0);phases["SOURCE_EVIDENCE_RERANK"]=phase("reranker",if scope["models"]["reranker"].is_null(){0}else{2},0);
 }else{let policy=s(&scope["context"]["proposal_policy_version"]);need(["source-learning-product-candidate-mvp-v1","source-learning-product-rebuild-candidate-mvp-v1","source-learning-product-candidate-mvp-batched-v1","source-learning-product-rebuild-candidate-mvp-batched-v1","source-learning-product-candidate-mvp-local-v1","source-learning-product-rebuild-candidate-mvp-local-v1","source-learning-product-candidate-mvp-batched-local-v1","source-learning-product-rebuild-candidate-mvp-batched-local-v1",crate::source_correction_v1::POLICY,crate::source_proposal_replay_v1::POLICY].contains(&policy)||reviewed_policy(policy),"SOURCE_EXECUTION_POLICY_UNSUPPORTED")?;if policy!=crate::source_correction_v1::POLICY&&!batched_policy(policy){phases["EXTRACTION"]=phase("generation",1,6000);}}
 let id=format!("auto_{}",&hash(&json!({"scope_sha256":h,"execution_key":k}))[..32]);let mut c=json!({"contract_version":VERSION,"mode":"AUTOMATIC_TASK_PLAN","id":id,"status":"AUTHORIZED","library_id":scope["source_stamp"]["base_id"],"scope_sha256":h,"execution_key":k,"phase_plan":phases,"index_plan_sha256":null,"extraction_plan_sha256":null,"used":{"generation":0,"embedding":0,"reranker":0},"reservations":[],"user_quota":false,"generation_output_policy":"PROVIDER_DEFAULT","automatic_retry":0});seal(&mut c);Ok(c)}
fn reserve(p:&Value)->Result<Value>{let scope=&p["scope"];let mut c=p["execution"].clone();check(&c,scope)?;let call=&p["call"];let req=s(&call["request_id"]);let name=s(&call["phase"]);let cap=s(&call["capability"]);need(!req.is_empty()&&["generation","embedding","reranker"].contains(&cap)&&!scope["models"][cap].is_null(),"SOURCE_EXECUTION_CALL_INVALID")?;need(!a(&c["reservations"]).iter().any(|r|r["request_id"]==req),"SOURCE_EXECUTION_REQUEST_ALREADY_RESERVED_NO_RESEND")?;
 // Any prior reserve lacking a known durable outcome remains conservatively unknown.
 for prior in a(&c["reservations"]){let seen:Vec<_>=a(&p["observations"]).iter().filter(|o|o["request_id"]==prior["request_id"]).collect();need(seen.len()==1&&["COMPLETED","RETURNED","BLOCKED_NOT_SENT"].contains(&s(&seen[0]["outcome"])),"SOURCE_EXECUTION_PRIOR_OUTCOME_UNKNOWN_NO_RESEND")?;}
 if name.starts_with("EXTRACTION_"){need(scope["context"]["operation"]=="SOURCE_LEARNING"&&batched_policy(s(&scope["context"]["proposal_policy_version"]))&&cap=="generation","SOURCE_EXECUTION_PHASE_INVALID")?;let job=&p["job"];let plan=&p["extraction_plan"];need(job["stage"]=="EXTRACTING"&&job["request"]["raw_question"]==scope["context"]["question"]&&job["request"]["policy_version"]==scope["context"]["proposal_policy_version"]&&job["snapshot"]["source_epoch"]==scope["snapshot"]["source_epoch"]&&job["snapshot"]["sources"]==scope["snapshot"]["sources"]&&a(&job["attempts"]).iter().all(|a|a["outcome"]=="RETURNED"||job["request"]["policy_version"]==crate::source_proposal_replay_v1::POLICY&&a["outcome"]=="CACHED_KNOWN_RESPONSE"),"SOURCE_EXECUTION_EXTRACTION_JOB_INVALID")?;if job["request"]["policy_version"]==crate::source_proposal_replay_v1::POLICY{crate::source_learning_v1::validate_job_archive(job)?;need(!a(&job["attempts"]).iter().any(|a|a["phase"]==name),"SOURCE_EXECUTION_PHASE_ALREADY_OBSERVED_NO_RESEND")?;}
 crate::fine_source_evidence::execute("validate_batches",&json!({"contract_version":"lightog-fine-source-evidence/0.1","evidence_set":job["evidence_set"],"context":p["extraction_context"],"refinement":plan}))?;let i=name.strip_prefix("EXTRACTION_").unwrap().parse::<usize>().map_err(|_|error("SOURCE_EXECUTION_PHASE_INVALID","SOURCE_EXECUTION_PHASE_INVALID"))?;need(i<a(&plan["batches"]).len(),"SOURCE_EXECUTION_EXTRACTION_PLAN_INVALID")?;if job["request"]["policy_version"]==crate::source_proposal_replay_v1::POLICY{need((0..i).all(|before|a(&job["attempts"]).iter().any(|a|a["phase"]==format!("EXTRACTION_{before:03}")&&["RETURNED","CACHED_KNOWN_RESPONSE"].contains(&s(&a["outcome"])))),"SOURCE_EXECUTION_CACHED_PREFIX_NOT_RECORDED")?;}let h=hash(plan);need(c["extraction_plan_sha256"].is_null()||c["extraction_plan_sha256"]==h,"SOURCE_EXECUTION_EXTRACTION_PLAN_CHANGED")?;c["extraction_plan_sha256"]=json!(h);for (i,_) in a(&plan["batches"]).iter().enumerate(){c["phase_plan"][format!("EXTRACTION_{i:03}")]=phase("generation",1,6000);}}
 if name.starts_with("SEMANTIC_STRUCTURE_REVIEW_")||name.starts_with("SEMANTIC_NARRATIVE_REVIEW_"){
  need(scope["context"]["operation"]=="SOURCE_LEARNING"&&reviewed_policy(s(&scope["context"]["proposal_policy_version"]))&&cap=="generation","SOURCE_EXECUTION_PHASE_INVALID")?;
  let job=&p["job"];let plan=&p["extraction_plan"];
  need(job["stage"]=="EXTRACTING"&&job["request"]["policy_version"]==scope["context"]["proposal_policy_version"]&&job["snapshot"]["source_epoch"]==scope["snapshot"]["source_epoch"]&&job["snapshot"]["sources"]==scope["snapshot"]["sources"]&&a(&job["attempts"]).iter().all(|a|a["outcome"]=="RETURNED"),"SOURCE_EXECUTION_REVIEW_JOB_INVALID")?;
  crate::fine_source_evidence::execute("validate_batches",&json!({"contract_version":"lightog-fine-source-evidence/0.1","evidence_set":job["evidence_set"],"context":p["extraction_context"],"refinement":plan}))?;
  let suffix=name.rsplit('_').next().unwrap_or("");let i=suffix.parse::<usize>().map_err(|_|error("SOURCE_EXECUTION_PHASE_INVALID","SOURCE_EXECUTION_PHASE_INVALID"))?;
  need(suffix.len()==3&&i<a(&plan["batches"]).len()&&a(&job["attempts"]).iter().any(|a|a["phase"]==format!("EXTRACTION_{i:03}")&&a["outcome"]=="RETURNED"),"SOURCE_EXECUTION_REVIEW_EXTRACTION_REQUIRED")?;
  if name.starts_with("SEMANTIC_NARRATIVE_REVIEW_"){need(a(&job["attempts"]).iter().any(|a|a["phase"]==format!("SEMANTIC_STRUCTURE_REVIEW_{i:03}")&&a["outcome"]=="RETURNED"),"SOURCE_EXECUTION_STRUCTURE_REVIEW_REQUIRED")?;}
  let h=hash(plan);need(c["extraction_plan_sha256"].is_null()||c["extraction_plan_sha256"]==h,"SOURCE_EXECUTION_EXTRACTION_PLAN_CHANGED")?;c["extraction_plan_sha256"]=json!(h);
  c["phase_plan"][name]=phase("generation",1,if name.starts_with("SEMANTIC_STRUCTURE_REVIEW_"){16000}else{8000});
 }
 if name.starts_with("INDEX_DOCUMENT_EMBEDDING_"){need(scope["context"]["operation"]=="SOURCE_LEARNING"&&cap=="embedding","SOURCE_EXECUTION_PHASE_INVALID")?;let plan=&p["index_plan"];let batches=plan["batches"].as_array().ok_or_else(||error("SOURCE_EXECUTION_INDEX_PLAN_INVALID","SOURCE_EXECUTION_INDEX_PLAN_INVALID"))?;let job=&p["job"];need(job["stage"]=="INDEX_PENDING"&&job["request"]["raw_question"]==scope["context"]["question"]&&job["request"]["policy_version"]==scope["context"]["proposal_policy_version"]&&job["snapshot"]["source_epoch"]==scope["snapshot"]["source_epoch"]&&job["snapshot"]["sources"]==scope["snapshot"]["sources"]&&a(&job["attempts"]).iter().all(|a|a["outcome"]=="RETURNED"||job["request"]["policy_version"]==crate::source_proposal_replay_v1::POLICY&&a["outcome"]=="CACHED_KNOWN_RESPONSE"),"SOURCE_EXECUTION_INDEX_JOB_INVALID")?;if job["request"]["policy_version"]==crate::source_proposal_replay_v1::POLICY{crate::source_learning_v1::validate_job_archive(job)?;}let i=name.strip_prefix("INDEX_DOCUMENT_EMBEDDING_").unwrap().parse::<usize>().map_err(|_|error("SOURCE_EXECUTION_PHASE_INVALID","SOURCE_EXECUTION_PHASE_INVALID"))?;need(i<batches.len()&&batches.iter().all(|b|b.as_array().is_some_and(|r|!r.is_empty()&&r.len()<=20&&r.iter().all(|t|t.as_str().is_some_and(|t|!t.trim().is_empty()))))&&call["text_count"]==batches[i].as_array().unwrap().len(),"SOURCE_EXECUTION_INDEX_PLAN_INVALID")?;let h=hash(plan);need(c["index_plan_sha256"].is_null()||c["index_plan_sha256"]==h,"SOURCE_EXECUTION_INDEX_PLAN_CHANGED")?;c["index_plan_sha256"]=json!(h);for (i,_) in batches.iter().enumerate(){c["phase_plan"][format!("INDEX_DOCUMENT_EMBEDDING_{i:03}")]=phase("embedding",1,0);}}
 let rule=&c["phase_plan"][name];need(rule["capability"]==cap&&a(&c["reservations"]).iter().filter(|r|r["phase"]==name).count()<(rule["planned_calls"].as_u64().unwrap_or(0) as usize),"SOURCE_EXECUTION_PHASE_PLAN_EXHAUSTED")?;if cap=="generation"{let provider_default=c["generation_output_policy"]=="PROVIDER_DEFAULT";need(if provider_default{call["max_tokens"].is_null()||call["max_tokens"].as_u64().is_some_and(|n|n>0)}else{call["max_tokens"].as_u64().is_some_and(|n|n>0&&n<=rule["max_output_tokens"].as_u64().unwrap_or(0))},"SOURCE_EXECUTION_OUTPUT_PLAN_CHANGED")?;}if cap=="embedding"{need(call["text_count"].as_u64().is_some_and(|n|(1..=20).contains(&n)),"SOURCE_EXECUTION_BATCH_INVALID")?;}
 let next=c["used"][cap].as_u64().unwrap().checked_add(1).ok_or_else(||error("SOURCE_EXECUTION_COUNTER_OVERFLOW","SOURCE_EXECUTION_COUNTER_OVERFLOW"))?;c["used"][cap]=json!(next);let r=json!({"request_id":req,"phase":name,"capability":cap,"index":next,"billing_status":"RESERVED_NOT_PROOF_OF_SEND"});c["reservations"].as_array_mut().unwrap().push(r.clone());seal(&mut c);Ok(json!({"execution":c,"reservation":r}))}
fn embedding(p:&Value)->Result<Value>{let c=&p["execution"];check(c,&p["scope"])?;let plan=&p["embedding_plan"];need(plan["status"]=="READY"&&plan["scope_sha256"]==c["scope_sha256"],"SOURCE_EXECUTION_EMBEDDING_PLAN_INVALID")?;for (field,name) in [("document_batches","SOURCE_DOCUMENT_EMBEDDING"),("query_batches","SOURCE_QUERY_EMBEDDING")]{let n=plan[field].as_u64().ok_or_else(||error("SOURCE_EXECUTION_EMBEDDING_PLAN_INVALID","SOURCE_EXECUTION_EMBEDDING_PLAN_INVALID"))?;let used=a(&c["reservations"]).iter().filter(|r|r["phase"]==name).count() as u64;need(n+used<=c["phase_plan"][name]["planned_calls"].as_u64().unwrap_or(0),"SOURCE_EXECUTION_EMBEDDING_PLAN_CHANGED")?;}Ok(json!({"automatic_execution_validated":true,"user_quota":false,"point_in_time_only":true}))}
fn admission(p:&Value)->Result<Value>{let r=&p["response"];let answer=&r["answer"];let current=&p["current_snapshot"];let same_source=answer["snapshot"]["base_ref"]==current["base_ref"]&&answer["snapshot"]["source_epoch"]==current["source_epoch"]&&answer["snapshot"]["sources"]==current["sources"];let valid=same_source&&r["provider_outcome_unknown"]==false&&["ANSWERED","PARTIAL"].contains(&s(&r["status"]))&&answer["verification"]["reviewed"]==true&&answer["coverage_scope"]=="RETRIEVED_SOURCE_FRAGMENTS_ONLY";let explicit=!a(&answer["gaps"]).is_empty()||a(&answer["requirement_coverage"]).iter().any(|x|x["decision"]!="COVERED");let profile_refs:BTreeSet<_>=a(&r["retrieval_trace"]["record_decisions"]).iter().filter(|x|s(&x["record_id"]).starts_with("profile:")&&["COVERED_LINK","ADDED_WHOLE_GROUP"].contains(&s(&x["reason"])) ).flat_map(|x|a(&x["evidence_ids"]).iter().map(s)).collect();let cited:BTreeSet<_>=a(&answer["statements"]).iter().flat_map(|x|a(&x["evidence_ids"]).iter().map(s)).collect();let graph_used=!cited.is_empty()&&cited.iter().all(|id|profile_refs.contains(id)||a(&r["citation_refinement"]["fragments"]).iter().find(|f|f["evidence_id"]==*id).is_some_and(|f|a(&f["parent_evidence_ids"]).iter().any(|p|profile_refs.contains(s(p)))));let reason=if !valid{"ANSWER_NOT_ELIGIBLE_FOR_AUTOMATIC_DISCOVERY"}else if explicit{"ANSWER_COVERAGE_GAP"}else if !graph_used{"GRAPH_COVERAGE_UNKNOWN"}else{"NO_MECHANICAL_DISCOVERY_TRIGGER"};Ok(json!({"contract_version":VERSION,"enqueue_discovery":valid&&(explicit||!graph_used),"reason":reason,"source_snapshot":answer["snapshot"],"question":answer["question"],"semantic_gap_certified":false,"graph_consumption_is_not_semantic_coverage":true,"publication_performed":false}))}
pub fn execute(op:&str,p:&Value)->Result<Value>{need(p["contract_version"]==VERSION,"SOURCE_EXECUTION_VERSION_INVALID")?;match op{"create"=>create(p),"validate"=>{check(&p["execution"],&p["scope"])?;Ok(p["execution"].clone())},"reserve"=>reserve(p),"validate_embedding"=>embedding(p),"learning_admission"=>admission(p),_=>Err(error("SOURCE_EXECUTION_OPERATION_UNKNOWN",op))}}

#[cfg(test)]
mod tests{
 use super::*;
 #[test]
 fn reviewed_batch_policy_is_admitted_without_an_unbatched_extraction_slot(){
  let scope=json!({"version":"lightog-source-product-budget/1","context":{"operation":"SOURCE_LEARNING","question":"What is supported?","proposal_policy_version":"source-learning-product-candidate-reviewed-batched-local-v1"},"source_stamp":{"base_id":"lib"},"snapshot":{},"models":{}});
  let execution=execute("create",&json!({"contract_version":VERSION,"scope":scope,"execution_key":"job","embedding_plan":null})).unwrap();
  assert_eq!(execution["status"],"AUTHORIZED");
  assert!(execution["phase_plan"].get("EXTRACTION").is_none());
  assert!(reviewed_policy("source-learning-product-rebuild-candidate-reviewed-batched-local-v1"));
 }
}
